INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6410011, 950928, 83313, '<td valign="top">Good composition, and a good effort, but I''m afraid the light is not flattering the subject or the background.</td>', 'Good composition, and a good effort, but I''m afraid the light is not flattering the subject or the background.', '2011-05-11 01:08:48.000000', NULL, 1),
(6410053, 950659, 83313, '<td valign="top">This seems quite blurred and unclear, with a ton of blocky artifacts visible throughout the image. Most of it is due to the use of excessive JPEG compression. Your file size of only 36k indicates a highly compressed image and that is what is robbing most of the detail and sharpness from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit (300k at this point in time). You''ve also got a serious tilt to this that would have been easy to correct.</td>', 'This seems quite blurred and unclear, with a ton of blocky artifacts visible throughout the image. Most of it is due to the use of excessive JPEG compression. Your file size of only 36k indicates a highly compressed image and that is what is robbing most of the detail and sharpness from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit (300k at this point in time). You''ve also got a serious tilt to this that would have been easy to correct.', '2011-05-11 01:20:47.000000', NULL, 1),
(6410084, 950357, 113142, '<td valign="top">There is almost an element of stopped motion here, like a propeller caught at high-speed. DOF is a little shallow, but might I assume improvised macro?</td>', 'There is almost an element of stopped motion here, like a propeller caught at high-speed. DOF is a little shallow, but might I assume improvised macro?', '2011-05-11 01:29:22.000000', NULL, 1),
(6410091, 950954, 113142, '<td valign="top">nice choice for gold subject! angle is not very exciting, though. Think of how a player would have the instrument at an angle while playing it . . .</td>', 'nice choice for gold subject! angle is not very exciting, though. Think of how a player would have the instrument at an angle while playing it . . .', '2011-05-11 01:30:39.000000', NULL, 1),
(6410096, 950175, 113142, '<td valign="top">Makes me think this was taken a long time ago when film required long exposures</td>', 'Makes me think this was taken a long time ago when film required long exposures', '2011-05-11 01:31:33.000000', NULL, 1),
(6410102, 950246, 113142, '<td valign="top">Oh, touching at my weak spot for mathematical appreciation *sigh* how irrational :) if only the DOF was a bit deeper. 6</td>', 'Oh, touching at my weak spot for mathematical appreciation *sigh* how irrational :) if only the DOF was a bit deeper. 6', '2011-05-11 01:33:30.000000', NULL, 1),
