(6421349, 950899, 118154, '<td valign="top">As I said one of my favs. Nice to see it ribbon.Congratulations.</td>', 'As I said one of my favs. Nice to see it ribbon.Congratulations.', '2011-05-22 13:16:16.000000', NULL, 0),
(6421627, 950899, 41746, '<td valign="top">Thank you all for these wonderful comments and the high score. I had my doubts submitting the image for the challenge because it is far from my style.. if I have any. But just as I was walking near my home one beautiful evening I noticed the golden pond and that kind of lonely duck that had just arrived. I took some shots and thought this was the best. As I write this on a sunny evening where the pond could be struck with the same gold - it is far away from that: we have black ash clouds over this part of Iceland due to the volcano erupting last night. Does not look good.</td>', 'Thank you all for these wonderful comments and the high score. I had my doubts submitting the image for the challenge because it is far from my style.. if I have any. But just as I was walking near my home one beautiful evening I noticed the golden pond and that kind of lonely duck that had just arrived. I took some shots and thought this was the best. As I write this on a sunny evening where the pond could be struck with the same gold - it is far away from that: we have black ash clouds over this part of Iceland due to the volcano erupting last night. Does not look good.', '2011-05-22 20:49:15.000000', NULL, 0),
(6422103, 950705, 93565, '<td valign="top">Man, you got hammered on this one!<br/>Well, I still appreciated the photo.</td>', 'Man, you got hammered on this one!Well, I still appreciated the photo.', '2011-05-23 05:13:01.000000', NULL, 0),
(6423731, 950954, 54446, '<td valign="top">I thought this was exceptionally well done and rewarded the image with a 9.</td>', 'I thought this was exceptionally well done and rewarded the image with a 9.', '2011-05-24 22:14:18.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6425082, 950601, 98339, '<td valign="top">This is really well done...it glows!!!</td>', 'This is really well done...it glows!!!', '2011-05-26 09:35:27.000000', NULL, 0),
(6425945, 950829, 100831, '<td valign="top">Love the repetition. And it just shimmers. Great work.</td>', 'Love the repetition. And it just shimmers. Great work.', '2011-05-27 09:47:56.000000', NULL, 0),
(6427880, 950937, 30982, '<td valign="top">Looks lovely to me!  Just goes to show what I don''t know.  I love the swirl of the syrup.</td>', 'Looks lovely to me!  Just goes to show what I don''t know.  I love the swirl of the syrup.', '2011-05-30 01:57:02.000000', NULL, 0),
(6433590, 950354, 103142, '<td valign="top">I gave this one a 6. I think the golds are lovely, but I think the undergrowth is too heavily processed. It makes the bottom of the shot very busy and draws the eyes away from gold. When the gold is that secondary, it doesn''t seem to fit the challenge as well as if you really made that the focus.</td>', 'I gave this one a 6. I think the golds are lovely, but I think the undergrowth is too heavily processed. It makes the bottom of the shot very busy and draws the eyes away from gold. When the gold is that secondary, it doesn''t seem to fit the challenge as well as if you really made that the focus.', '2011-06-03 23:25:53.000000', NULL, 0),
(6508656, 951017, 61788, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ScooterMcNutty:</b></div><hr/><i> what is the point of the mirrors? </i></td></tr></table> <br/>Mirrors in this case do not have any special meaning. They are part of composition pretty much same way as shadows created by blinds or golden box :)</td>', 'Originally posted by ScooterMcNutty: what is the point of the mirrors?  Mirrors in this case do not have any special meaning. They are part of composition pretty much same way as shadows created by blinds or golden box :)', '2011-08-18 23:17:53.000000', NULL, 0),
(6919833, 950874, 116247, '<td valign="top">Reminds me of a Doctor Seuss image for some reason! Love the lighting.</td>', 'Reminds me of a Doctor Seuss image for some reason! Love the lighting.', '2012-12-02 19:21:58.000000', NULL, 0),
(7100799, 950663, 136989, '<td valign="top">Wow! That''s a lot of flowers!  I like how the blue, yellow and green compliment one another.  Gorgeous shot.</td>', 'Wow! That''s a lot of flowers!  I like how the blue, yellow and green compliment one another.  Gorgeous shot.', '2013-09-08 23:30:51.000000', NULL, 0),
(7221800, 950874, 152252, '<td valign="top">They look yummy. You definitely put them in a good light :) Love the title</td>', 'They look yummy. You definitely put them in a good light :) Love the title', '2014-05-28 20:48:23.000000', NULL, 0),
(7221805, 950874, 150277, '<td valign="top">Great job with the lighting, especially for a basic editing challenge.  Well done.</td>', 'Great job with the lighting, especially for a basic editing challenge.  Well done.', '2014-05-28 20:51:20.000000', NULL, 0),
